package org.grit.daynomy.support;

import java.sql.Connection;
import java.util.ArrayList;
import java.util.List;
import javax.sql.DataSource;

final class DatabaseCleaner {
  private static boolean initialized;
  private static String truncate;

  private DatabaseCleaner() {}

  static synchronized void reset(DataSource dataSource) throws Exception {
    try (Connection connection = dataSource.getConnection();
        var statement = connection.createStatement()) {
      if (!initialized) {
        // Preserve the exact baseline generated by Flyway, including audit columns.
        statement.execute("CREATE SCHEMA test_baseline");
        statement.execute(
            "CREATE TABLE test_baseline.market_trading_days AS TABLE public.market_trading_days");
        List<String> tables = new ArrayList<>();
        try (var results =
            statement.executeQuery(
                "SELECT tablename FROM pg_tables WHERE schemaname = 'public' AND tablename <> 'flyway_schema_history' ORDER BY tablename")) {
          while (results.next())
            tables.add("public.\"" + results.getString(1).replace("\"", "\"\"") + "\"");
        }
        truncate = "TRUNCATE TABLE " + String.join(", ", tables) + " RESTART IDENTITY CASCADE";
        initialized = true;
      }
      connection.setAutoCommit(false);
      statement.execute(truncate);
      statement.execute(
          "INSERT INTO public.market_trading_days SELECT * FROM test_baseline.market_trading_days");
      connection.commit();
    }
  }
}
